carregarMais(): void {
  const antes = this.itens().length;

  this.servico.pagina(this.pagina++).subscribe((novos) => {
    this.itens.update((atual) => [...atual, ...novos]);

    // Anuncia o que chegou, sem mover o foco.
    this.announcer.announce(
      `${novos.length} itens carregados. ${this.itens().length} de ${this.total()}.`,
      'polite',
    );

    // Foco no primeiro item novo, para quem usa teclado
    // continuar de onde parou em vez de voltar ao topo.
    queueMicrotask(() => this.itemRefs()[antes]?.nativeElement.focus());
  });
}

mover(de: number, delta: number): void {
  const para = de + delta;
  const lista = [...this.tarefas()];
  const [item] = lista.splice(de, 1);
  lista.splice(para, 0, item);
  this.tarefas.set(lista);

  // Sem anúncio, a pessoa não tem como saber que funcionou:
  // o item mudou de lugar numa lista que ela não vê.
  this.announcer.announce(
    `${item.titulo} movido para a posição ${para + 1} de ${lista.length}`,
    'polite',
  );

  // O foco tem que seguir o item, não a posição.
  queueMicrotask(() => this.botoes()[para]?.nativeElement.focus());
}

